class Ratchet:
    """The companion's Ratchet, trimmed: rules in memory, each new one mirrored to a file."""
    def __init__(self, rules=None, path=None):
        self.rules = list(rules or [])
        self.path = path

    def learn(self, rule):
        if rule in self.rules:
            return False
        self.rules.append(rule)
        if self.path is not None:
            with open(self.path, "a", encoding="utf-8") as fh:
                fh.write(rule + "\n")
        return True


def start_session(path):
    """Begin a session whose ratchet holds every rule already in the file at `path` (a missing
    file holds none), each once, in the order first written, so that a rule learned in an
    earlier session is neither forgotten nor appended again."""
    rules = []
    try:
        with open(path, encoding="utf-8") as fh:
            for line in fh:
                rule = line.rstrip("\n")
                if rule.strip() and rule not in rules:
                    rules.append(rule)
    except FileNotFoundError:
        pass
    return Ratchet(rules=rules, path=path)
